"""Post-process an autogenerated Alembic migration.

Autogenerate renders each VARCHAR enum's CHECK twice: once from ``Enum(create_constraint=True)``
on the column and once as an explicit table constraint. Keep only the convention-named
``op.f(...)`` constraint and stop the column from emitting its own. Usage:

    uv run python scripts/fix_enum_checks.py migrations/versions/<file>.py
"""

import re
import sys
from pathlib import Path

path = Path(sys.argv[1])
src = path.read_text()
src = re.sub(r"    sa\.CheckConstraint\([^\n]*, name='[a-z_]+'\),\n", "", src)
src = src.replace("create_constraint=True", "create_constraint=False")
path.write_text(src)
print(f"fixed {path}")
